-- Real product photos for the 2026 catalog, hosted on Cloudflare R2 (bucket `crackers-pics`).
-- Source: the shop's own photos (crackerspic/), background removed, label rotated upright,
-- compressed to WebP (<= 500 KB, <= 1600 px). Object keys are content-hashed, so a re-shot
-- photo gets a new URL. Only products still on a bundled placeholder image are changed, so
-- anything an admin has already set by hand is kept. 113 products; the rest keep their
-- category placeholder until a photo exists.

UPDATE products AS p
SET image_url = v.image_url, version = p.version + 1, updated_at = now()
